/** Pure prompt assembly from upstream app/prompts.ts; filesystem resources and version storage are separate host boundaries. */
import {z} from 'zod';
import {key} from './vendor/src/core/index.ts';
import {policyVersion,type Settings} from './upstream-policy';
import {promptResources as resources,githubSkill,feishuSkill} from './upstream-prompt-resources';
const sharedPrompt=resources.shared,masterPrompt=resources.orchestrator,workerPrompt=resources.worker;
const guides:Record<string,string>={subscriptions:resources.subscriptions,replies:resources.replies,dispatch:resources.dispatch,work:resources.work};
const mainAdmissionPolicy=resources.admission;
const handoffPolicy=(role:'orchestrator'|'worker')=>resources.handoff+'\n'+(role==='orchestrator'?resources['handoff-orchestrator']:resources['handoff-worker']);
const teamDefaults={communication:resources['team/communication'],scope:resources['team/scope'],delivery:resources['team/delivery']};
const sourceSkills:Record<'github'|'feishu',string>={github:githubSkill,feishu:feishuSkill};
const cliNotes=resources.cli;
type Variable={name:string;value:string};
const environmentLines=(variables:Variable[])=>variables.map(v=>v.name+'='+v.value).join('\n');

/** Unchanged pure projections and notice rules extracted from upstream app/cards.ts and app/notices.ts. */
import {key,latestReport,ticketStage,type Ticket,type WorkerReport} from './vendor/src/core/index.ts';
const SOURCE='github';

/** Original assessment and routing argument schemas; dependencies bind to the Bridge host. */
import {z} from 'zod';
import {AdmissionDirectionSchema,RuleAssessmentSchema,directionAllowed} from './upstream-policy';
import {IM_WORDS,wordCount} from './vendor/src/infra/text.ts';

/** Original routing argument checks and decision execution, invoked through chat.task. */
import {z} from 'zod';
import {reasonText,type Decision,type DecisionKind,type Engine,type Repositories} from './vendor/src/core/index.ts';
import {IM_WORDS,NOTE_WORDS,wordCount} from './vendor/src/infra/text.ts';
import {WorktreeNameSchema} from './upstream-assessment';
interface MainToolsHost {engine:Engine;store:Repositories;quietly<T>(body:()=>T):T}

export {RouteItemSchema};
export function routeOriginal(engine:Engine,store:Repositories,value:unknown){
 const item=RouteItemSchema.parse(value),problem=invalid(item);
 if(problem)throw new Error(problem);
 return route({engine,store,quietly:body=>body()},item,new Map());
}
